    var px=50,py=35;
    slot.innerHTML='<div class="tut-full-form"><div class="tfg-edicao"><b>💬 Texto na gravação</b><textarea id="tfg-texto" class="tut-input" rows="2" placeholder="Escreva a instrução ou comentário"></textarea><details><summary>🎨 Formatar texto e caixa</summary><div class="tfg-estilo"><label>Tamanho<input id="tfg-tam" type="number" min="12" max="36" value="18" class="tut-input"></label><label>Texto<input id="tfg-cor" type="color" value="#1c1b18" class="tut-input"></label><label>Caixa<input id="tfg-fundo" type="color" value="#fff3cd" class="tut-input"></label><label>Borda<input id="tfg-borda" type="color" value="#e67e22" class="tut-input"></label></div><div class="tut-actions"><label><input id="tfg-b" type="checkbox" checked> Negrito</label><label><input id="tfg-i" type="checkbox"> Itálico</label><label><input id="tfg-u" type="checkbox"> Sublinhado</label></div></details><div class="tut-actions"><button class="tut-btn" id="tfg-posicionar">Posicionar na tela</button><button class="tut-btn sec" id="tfg-cancel">Cancelar</button></div></div><div class="tfg-dock"><span>Arraste o texto até o lugar certo</span><button class="tut-btn sec" id="tfg-editar">Editar</button><button class="tut-btn" id="tfg-ok">Salvar</button><button class="tut-btn sec" id="tfg-cancel2" aria-label="Cancelar texto">×</button></div></div>';
    var painel=slot.querySelector('.tut-full-form');
